function s(k,v){localStorage.setItem(k,JSON.stringify(v))}

// ------ IndexedDB для чата ------
let db=null;const DB_NAME='MTOChatDB',DB_VERSION=1;
function openDB(){return new Promise((resolve,reject)=>{if(db){resolve(db);return}const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=e=>{const d=e.target.result;if(!d.objectStoreNames.contains('messages')){const st=d.createObjectStore('messages',{keyPath:'id'});st.createIndex('room','room',{unique:false});st.createIndex('timestamp','timestamp',{unique:false})}};r.onsuccess=e=>{db=e.target.result;resolve(db)};r.onerror=e=>reject(e.target.error)})}
async function saveMsg(room,msg){const db=await openDB();const tx=db.transaction('messages','readwrite');const st=tx.objectStore('messages');st.add({...msg,room,id:Date.now()+'_'+Math.random().toString(36).slice(2,6)});return new Promise((resolve,reject)=>{tx.oncomplete=()=>resolve();tx.onerror=e=>reject(e.target.error)})}
async function getMsgs(room){const db=await openDB();const tx=db.transaction('messages','readonly');const st=tx.objectStore('messages');const idx=st.index('room');return new Promise((resolve,reject)=>{const r=idx.getAll(room);r.onsuccess=()=>resolve(r.result);r.onerror=e=>reject(e.target.error)})}

