function getAllPaths(tree,prefix=''){let paths=[];const cur=prefix?prefix+' / '+tree.name:tree.name;if(tree.children){for(const child of tree.children)paths=paths.concat(getAllPaths(child,cur))}else paths.push(cur);return paths}
