// ------ Вспомогательные ------
function genId(){return Date.now()+Math.floor(Math.random()*1000)}
function logAudit(user,action,details){const logs=g(S.audit);logs.push({time:new Date().toLocaleString(),user,action,details});s(S.audit,logs)}
function showToast(msg,type='info'){const c=document.getElementById('toastContainer');const t=document.createElement('div');t.className='toast '+type;t.innerHTML='<span>'+msg+'</span><button class="close-toast">&times;</button>';c.appendChild(t);t.querySelector('.close-toast').onclick=()=>t.remove();setTimeout(()=>t.remove(),5000)}
function getStatusBadge(st){const map={new:'Новая',work:'В работе',done:'Выполнена',rejected:'Отклонена',planned:'Запланирована',process:'В процессе'};const cls=st==='new'?'new':st==='work'?'work':st==='done'?'done':st==='rejected'?'rejected':st==='planned'?'planned':'process';return '<span class="status-badge status-'+cls+'">'+(map[st]||st)+'</span>'}
function getPriorityLabel(p){const map={low:'Низкий',medium:'Средний',high:'Высокий'};return map[p]||p}
function isAdmin(user){if(!user)return false;if(user.login==='admin')return true;if(user.deptPath&&user.deptPath.includes('Администрация'))return true;return false}
function getUserRole(user){if(!user)return 'guest';if(isAdmin(user))return 'admin';if(user.deptPath&&user.deptPath.includes('Начальник склада'))return 'warehouse';if(user.deptPath&&user.deptPath.includes('Диспетчерская'))return 'dispatcher';return 'employee'}

