let currentUser=null;
function loadSession(){const st=localStorage.getItem(S.currentUser);if(st){try{currentUser=JSON.parse(st);return true}catch(e){return false}}return false}
function saveSession(u){localStorage.setItem(S.currentUser,JSON.stringify(u))}
function loginUser(login,password){const users=g(S.users);const found=users.find(u=>u.login===login&&u.password===password);if(found){currentUser=found;saveSession(found);logAudit(login,'Вход в систему','Успешный вход');showToast('Добро пожаловать, '+(found.displayName||login)+'!','success');if('Notification' in window&&Notification.permission==='default')Notification.requestPermission();return true}return false}
function registerUser(login,password,deptPath,displayName,phone,email,position,birthDate,avatarBase64){const users=g(S.users);if(users.find(u=>u.login===login))return false;const newUser={login,password,displayName:displayName||login,phone:phone||'',email:email||'',position:position||'',birthDate:birthDate||'',avatar:avatarBase64||'',deptPath:deptPath||'Диспетчерская'};users.push(newUser);s(S.users,users);logAudit(login,'Регистрация','Новый пользователь');const sch=g(S.schedule);sch[login]={mon:'day',tue:'day',wed:'day',thu:'day',fri:'day',sat:'off',sun:'off'};s(S.schedule,sch);return true}
function logoutUser(){if(currentUser)logAudit(currentUser.login,'Выход','');currentUser=null;localStorage.removeItem(S.currentUser);showToast('Вы вышли','info')}
function oauthLogin(provider){const fakeLogin='user_'+provider+'_'+Date.now().toString(36);const fakePassword='pass_'+Math.random().toString(36);const users=g(S.users);let existing=users.find(u=>u.login===fakeLogin);if(!existing)registerUser(fakeLogin,fakePassword,'Диспетчерская','Пользователь '+provider,'','','','','');loginUser(fakeLogin,fakePassword);document.getElementById('authOverlay').classList.add('hidden');initAppAfterLogin();showToast('Вход через '+provider+' выполнен','success')}

