function createRequest(title,desc,type,address,deptPath,priority,status,deadline,creator,responsible){const reqs=getRequests();const newReq={id:genId(),title,desc,type,address,deptPath,priority,status,deadline,creator,responsible:responsible||creator,created:Date.now(),updated:Date.now()};reqs.push(newReq);saveRequests(reqs);logAudit(creator,'Создание заявки','#'+newReq.id+' "'+title+'"');showToast('Заявка #'+newReq.id+' создана','success');return newReq}
function updateRequest(id,data){const reqs=getRequests();const idx=reqs.findIndex(r=>r.id===id);if(idx===-1)return false;const old=reqs[idx];reqs[idx]={...old,...data,updated:Date.now()};saveRequests(reqs);logAudit(currentUser.login,'Изменение заявки','#'+id+' "'+old.title+'"');showToast('Заявка #'+id+' обновлена','info');return true}
function deleteRequest(id){let reqs=getRequests();const found=reqs.find(r=>r.id===id);if(!found)return false;reqs=reqs.filter(r=>r.id!==id);saveRequests(reqs);logAudit(currentUser.login,'Удаление заявки','#'+id+' "'+found.title+'"');showToast('Заявка #'+id+' удалена','error');return true}

