function updateRoute(id,data){const routes=getRoutes();const idx=routes.findIndex(r=>r.id===id);if(idx===-1)return false;routes[idx]={...routes[idx],...data};saveRoutes(routes);logAudit(currentUser.login,'Изменение маршрута','#'+id);showToast('Маршрут обновлён','info');return true}
function deleteRoute(id){let routes=getRoutes();const found=routes.find(r=>r.id===id);if(!found)return false;routes=routes.filter(r=>r.id!==id);saveRoutes(routes);logAudit(currentUser.login,'Удаление маршрута','#'+id);showToast('Маршрут удалён','error');return true}
function getRepairs(){return g(S.repairs)}
function saveRepairs(r){s(S.repairs,r)}
function addRepair(vehicle,reason,startDate,status){const repairs=getRepairs();const newRep={id:genId(),vehicle,reason,startDate,status};repairs.push(newRep);saveRepairs(repairs);logAudit(currentUser.login,'Добавление ремонта',vehicle);showToast('Ремонт для '+vehicle+' добавлен','success');return newRep}
function completeRepair(id){let repairs=getRepairs();const found=repairs.find(r=>r.id===id);if(!found)return false;repairs=repairs.filter(r=>r.id!==id);saveRepairs(repairs);logAudit(currentUser.login,'Завершение ремонта',found.vehicle);showToast('Ремонт '+found.vehicle+' завершён','success');return true}

