function updateProcurement(id,data){const procs=getProcurements();const idx=procs.findIndex(p=>p.id===id);if(idx===-1)return false;procs[idx]={...procs[idx],...data};saveProcurements(procs);logAudit(currentUser.login,'Изменение закупки','#'+id+' '+procs[idx].name);showToast('Закупка обновлена','info');return true}
function deleteProcurement(id){let procs=getProcurements();const found=procs.find(p=>p.id===id);if(!found)return false;procs=procs.filter(p=>p.id!==id);saveProcurements(procs);logAudit(currentUser.login,'Удаление закупки',found.name);showToast('Закупка "'+found.name+'" удалена','error');return true}

// ------ Материалы ------
function getMaterials(){return g(S.materials)}
function saveMaterials(m){s(S.materials,m)}
function getSupplies(){return g(S.supplies)}
function saveSupplies(sup){s(S.supplies,sup)}
function addMaterial(name,category,unit,quantity,reserve){const mats=getMaterials();const newMat={id:genId(),name,category,unit,quantity:parseInt(quantity)||0,reserve:parseInt(reserve)||0};mats.push(newMat);saveMaterials(mats);logAudit(currentUser.login,'Добавление материала',name+' ('+category+')');showToast('Материал "'+name+'" добавлен','success');return newMat}
function updateMaterial(id,data){const mats=getMaterials();const idx=mats.findIndex(m=>m.id===id);if(idx===-1)return false;mats[idx]={...mats[idx],...data};saveMaterials(mats);logAudit(currentUser.login,'Изменение материала','#'+id+' '+mats[idx].name);showToast('Материал обновлён','info');return true}
function deleteMaterial(id){let mats=getMaterials();const found=mats.find(m=>m.id===id);if(!found)return false;mats=mats.filter(m=>m.id!==id);saveMaterials(mats);logAudit(currentUser.login,'Удаление материала',found.name);showToast('Материал "'+found.name+'" удалён','error');return true}
function addSupply(materialName,quantity){const supplies=getSupplies();const newSup={id:genId(),material:materialName,quantity:parseInt(quantity)||0,date:new Date().toLocaleString(),type:'приход'};supplies.push(newSup);saveSupplies(supplies);const mats=getMaterials();const mat=mats.find(m=>m.name===materialName);if(mat){mat.quantity+=parseInt(quantity)||0;saveMaterials(mats)}logAudit(currentUser.login,'Поставка материала',materialName+' +'+quantity);showToast('Поставка '+materialName+' +'+quantity,'success');return newSup}
function reserveMaterial(id,amount){const mats=getMaterials();const mat=mats.find(m=>m.id===id);if(!mat)return false;const avail=mat.quantity-mat.reserve;if(avail<amount){showToast('Недостаточно доступного количества','error');return false}mat.reserve+=amount;saveMaterials(mats);logAudit(currentUser.login,'Резервирование материала',mat.name+' +'+amount);showToast('Зарезервировано '+amount+' '+mat.unit,'info');return true}
function issueMaterial(id,amount){const mats=getMaterials();const mat=mats.find(m=>m.id===id);if(!mat)return false;const avail=mat.quantity-mat.reserve;if(avail<amount){showToast('Недостаточно доступного количества','error');return false}mat.quantity-=amount;saveMaterials(mats);logAudit(currentUser.login,'Выдача материала',mat.name+' -'+amount);showToast('Выдано '+amount+' '+mat.unit,'info');return true}

