// ------ Новости (Яндекс) ------
async function fetchNews(limit=5,containerId='newsFeedList'){const c=document.getElementById(containerId);if(c)c.innerHTML='Загрузка...';try{const proxy='https://api.allorigins.win/raw?url=';const rss='https://news.yandex.ru/news.rss';const resp=await fetch(proxy+encodeURIComponent(rss));if(!resp.ok)throw new Error('Ошибка');const txt=await resp.text();const parser=new DOMParser();const xml=parser.parseFromString(txt,'text/xml');const items=xml.querySelectorAll('item');let html='';let count=0;items.forEach(item=>{if(count>=limit)return;const title=item.querySelector('title')?.textContent||'Без названия';const pub=item.querySelector('pubDate')?.textContent||'';const link=item.querySelector('link')?.textContent||'#';html+='<div class="news-item"><div class="title"><a href="'+link+'" target="_blank" style="color:var(--primary);text-decoration:none;">'+title+'</a></div><div class="date">'+pub+'</div></div>';count++});if(c)c.innerHTML=html||'<p style="color:var(--text-secondary);">Новостей нет</p>'}catch(e){if(c)c.innerHTML='<p style="color:var(--text-secondary);">Не удалось загрузить новости</p>'}}

// ------ Погода с прогнозом ------
async function fetchWeather(city='Moscow'){const temp=document.getElementById('weatherTemp');const desc=document.getElementById('weatherDesc');const cityEl=document.getElementById('weatherCity');const fore=document.getElementById('weatherForecast');try{const key='e3e0f9f7f0e5d4c3b2a10987654321';const url=`https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${key}&units=metric&lang=ru`;const resp=await fetch(url);if(!resp.ok)throw new Error('Город не найден');const data=await resp.json();temp.textContent=Math.round(data.main.temp)+'°C';desc.textContent=data.weather[0].description;cityEl.textContent=data.name;const fUrl=`https://api.openweathermap.org/data/2.5/forecast?q=${city}&appid=${key}&units=metric&lang=ru&cnt=5`;const fResp=await fetch(fUrl);if(fResp.ok){const fData=await fResp.json();const days=fData.list.slice(0,5);fore.innerHTML=days.map(d=>{const date=new Date(d.dt*1000).toLocaleDateString('ru-RU',{weekday:'short',day:'numeric'});return '<div class="day"><div class="date">'+date+'</div><div class="temp">'+Math.round(d.main.temp)+'°</div><div style="font-size:12px;color:var(--text-secondary);">'+d.weather[0].description+'</div></div>'}).join('')}else fore.innerHTML=''}catch(e){temp.textContent='--°C';desc.textContent='Ошибка';cityEl.textContent=city;fore.innerHTML=''}}

