function populateDeptSelects(){const paths=getDeptList();const selects=document.querySelectorAll('#authDeptPath, #profileDeptPath, #reqDept');selects.forEach(sel=>{const cur=sel.value;sel.innerHTML='';paths.forEach(p=>{const opt=document.createElement('option');opt.value=p;opt.textContent=p;sel.appendChild(opt)});if(cur&&paths.includes(cur))sel.value=cur})}

function renderDashboard(){const data=deptData['default'];const s=data.stats;statsContainer.innerHTML='<div class="mto-stat"><h1>'+s.orders+'</h1><p>Заявок</p></div><div class="mto-stat"><h1>'+s.transport+'</h1><p>Транспорт</p></div><div class="mto-stat"><h1>'+s.employees+'</h1><p>Сотрудников</p></div><div class="mto-stat"><h1>'+s.completed+'</h1><p>Выполнено</p></div>';recentOrders.innerHTML=data.recentOrders.map(i=>'<li>'+i+'</li>').join('');kpiGrid.innerHTML=data.kpi.map(k=>'<div class="mto-kpi-item"><h4>'+k.label+'</h4><div class="value">'+k.value+'</div></div>').join('');activityList.innerHTML=data.activity.map(i=>'<li>'+i+'</li>').join('');erpLogItems.innerHTML=data.erpLog.map(i=>'<div class="mto-erp-log-item">'+i+'</div>').join('');fetchNews(5,'newsFeedList');fetchWeather('Moscow');setTimeout(initMaps,500);renderMyTasks();renderCalendar()}

function renderMyTasks(){const container=document.getElementById('myTasks');if(!currentUser){container.innerHTML='Войдите для просмотра';return}const reqs=getRequests().filter(r=>r.responsible===currentUser.login||r.creator===currentUser.login);if(!reqs.length){container.innerHTML='Нет активных задач';return}container.innerHTML=reqs.slice(0,5).map(r=>'<div style="padding:6px 0;border-bottom:1px solid rgba(0,0,0,0.04);">#'+r.id+' '+r.title+' — '+getStatusBadge(r.status)+'</div>').join('')}

function renderCalendar(){const container=document.getElementById('calendarWidget');const now=new Date();const year=now.getFullYear();const month=now.getMonth();const first=new Date(year,month,1);const last=new Date(year,month+1,0);const days=[];for(let d=1;d<=last.getDate();d++)days.push(new Date(year,month,d));let html='';days.forEach(d=>{const isToday=d.toDateString()===now.toDateString();const isWeekend=d.getDay()===0||d.getDay()===6;html+='<div class="day'+(isToday?' today':'')+(isWeekend?' weekend':'')+'">'+d.getDate()+'</div>'});container.innerHTML=html}

function renderTransport(){const data=deptData['default'];if(data.transportList.length){transportGrid.innerHTML=data.transportList.map(t=>'<div class="mto-card"><h3>'+t.name+'</h3><p style="color:var(--text-secondary);">'+t.plate+'</p><span class="mto-vehicle-tag" style="background:'+t.color+'">'+t.status+'</span></div>').join('')}else transportGrid.innerHTML='<p style="grid-column:1/-1;text-align:center;color:var(--text-secondary);">Нет транспорта</p>';renderRoutes();renderRepairVehicles()}
function renderRoutes(){const filter=document.getElementById('routeFilterStatus').value;let routes=getRoutes();if(filter!=='all')routes=routes.filter(r=>r.status===filter);if(!routes.length){routesBody.innerHTML='<tr><td colspan="7" style="text-align:center;color:var(--text-secondary);">Нет маршрутов</td></tr>';return}routesBody.innerHTML=routes.map(r=>'<tr><td>'+r.vehicle+'</td><td><span class="route-tag">'+(r.type==='supply'?'Поставка':r.type==='shipment'?'Отправка':'Перевоз')+'</span></td><td>'+r.from+'</td><td>'+r.to+'</td><td>'+getStatusBadge(r.status)+'</td><td>'+r.date+'</td><td><button class="btn btn-warning btn-sm edit-route" data-id="'+r.id+'">✏️</button><button class="btn btn-danger btn-sm delete-route" data-id="'+r.id+'">🗑️</button></td></tr>').join('');document.querySelectorAll('.edit-route').forEach(b=>b.addEventListener('click',function(){openEditRoute(parseInt(this.dataset.id))}));document.querySelectorAll('.delete-route').forEach(b=>b.addEventListener('click',function(){if(confirm('Удалить маршрут?')){deleteRoute(parseInt(this.dataset.id));renderRoutes()}}))}
function renderRepairVehicles(){const repairs=getRepairs();if(!repairs.length){repairContainer.innerHTML='<p>Нет техники на ремонте</p>';return}repairContainer.innerHTML=repairs.map(r=>'<div class="mto-card"><h3>'+r.vehicle+'</h3><p>Причина: '+r.reason+'</p><p>Начало: '+r.startDate+'</p><p>Статус: '+r.status+'</p><button class="btn btn-warning btn-sm" onclick="completeRepair('+r.id+')">Завершить</button><button class="btn btn-primary btn-sm" onclick="createRepairRequest('+r.id+')">Заявка на ремонт</button></div>').join('')}
window.completeRepair=function(id){completeRepair(id);renderRepairVehicles()};
window.createRepairRequest=function(id){const repairs=getRepairs();const found=repairs.find(r=>r.id===id);if(!found)return;createRequest('Ремонт '+found.vehicle,'Причина: '+found.reason,'repair','',currentUser.deptPath,'high','new',new Date().toISOString().split('T')[0],currentUser.login,currentUser.login);showToast('Заявка на ремонт создана','success')};

function renderRequests(){const statusFilter=document.getElementById('reqFilterStatus').value;const typeFilter=document.getElementById('reqFilterType').value;let reqs=getRequests();if(statusFilter!=='all')reqs=reqs.filter(r=>r.status===statusFilter);if(typeFilter!=='all')reqs=reqs.filter(r=>r.type===typeFilter);if(currentUser&&!isAdmin(currentUser)){reqs=reqs.filter(r=>r.deptPath===currentUser.deptPath||r.creator===currentUser.login||r.responsible===currentUser.login)}if(!reqs.length){requestsBody.innerHTML='<tr><td colspan="8" style="text-align:center;color:var(--text-secondary);">Нет заявок</td></tr>';return}requestsBody.innerHTML=reqs.map(r=>'<tr><td>#'+r.id+'</td><td>'+r.title+'</td><td>'+(r.type==='repair'?'Ремонт':r.type==='supply'?'Поставка':r.type==='transport'?'Перевозка':'Другое')+'</td><td>'+getStatusBadge(r.status)+'</td><td class="'+getPriorityClass(r.priority)+'">'+getPriorityLabel(r.priority)+'</td><td>'+(r.responsible||'—')+'</td><td>'+(canEditRequest(r)?'<button class="btn btn-primary btn-sm edit-req" data-id="'+r.id+'">✏️</button>':'')+(canDeleteRequest(r)?'<button class="btn btn-danger btn-sm delete-req" data-id="'+r.id+'">🗑️</button>':'')+(canChangeStatus(r)?'<select class="status-change" data-id="'+r.id+'"><option value="new">Новая</option><option value="work">В работе</option><option value="done">Выполнена</option><option value="rejected">Отклонена</option></select>':'')+'<button class="btn btn-success btn-sm pdf-req" data-id="'+r.id+'">PDF</button></td></tr>').join('');document.querySelectorAll('.edit-req').forEach(b=>b.addEventListener('click',function(){openEditRequest(parseInt(this.dataset.id))}));document.querySelectorAll('.delete-req').forEach(b=>b.addEventListener('click',function(){if(confirm('Удалить заявку?')){deleteRequest(parseInt(this.dataset.id));renderRequests()}}));document.querySelectorAll('.status-change').forEach(sel=>sel.addEventListener('change',function(){const id=parseInt(this.dataset.id);const newStatus=this.value;updateRequest(id,{status:newStatus});renderRequests()}));document.querySelectorAll('.pdf-req').forEach(b=>b.addEventListener('click',function(){exportRequestPDF(parseInt(this.dataset.id))}))}
function canEditRequest(req){if(!currentUser)return false;if(isAdmin(currentUser))return true;if(currentUser.deptPath===req.deptPath)return true;return false}
function canDeleteRequest(req){if(!currentUser)return false;if(isAdmin(currentUser))return true;if(currentUser.login===req.creator)return true;return false}
function canChangeStatus(req){if(!currentUser)return false;if(isAdmin(currentUser))return true;if(currentUser.deptPath===req.deptPath||currentUser.login===req.responsible)return true;return false}

function renderMaterials(){const catFilter=document.getElementById('matCategoryFilter').value;let mats=getMaterials();if(catFilter!=='all')mats=mats.filter(m=>m.category===catFilter);if(!mats.length){materialsBody.innerHTML='<tr><td colspan="7" style="text-align:center;color:var(--text-secondary);">Нет материалов</td></tr>';return}materialsBody.innerHTML=mats.map(m=>'<tr><td>'+m.name+'</td><td><span class="category-tag">'+m.category+'</span></td><td>'+m.unit+'</td><td>'+m.quantity+'</td><td>'+m.reserve+'</td><td>'+(m.quantity-m.reserve)+'</td><td><button class="btn btn-warning btn-sm edit-mat" data-id="'+m.id+'">✏️</button><button class="btn btn-danger btn-sm delete-mat" data-id="'+m.id+'">🗑️</button><button class="btn btn-success btn-sm issue-mat" data-id="'+m.id+'">Выдать</button><button class="btn btn-primary btn-sm reserve-mat" data-id="'+m.id+'">Резерв</button><button class="btn btn-success btn-sm pdf-mat" data-id="'+m.id+'">PDF</button></td></tr>').join('');document.querySelectorAll('.edit-mat').forEach(b=>b.addEventListener('click',function(){openEditMaterial(parseInt(this.dataset.id))}));document.querySelectorAll('.delete-mat').forEach(b=>b.addEventListener('click',function(){if(confirm('Удалить материал?')){deleteMaterial(parseInt(this.dataset.id));renderMaterials()}}));document.querySelectorAll('.issue-mat').forEach(b=>b.addEventListener('click',function(){const id=parseInt(this.dataset.id);const amount=prompt('Введите количество для выдачи:');if(amount&&!isNaN(amount)&&Number(amount)>0){issueMaterial(id,Number(amount));renderMaterials()}}));document.querySelectorAll('.reserve-mat').forEach(b=>b.addEventListener('click',function(){const id=parseInt(this.dataset.id);const amount=prompt('Введите количество для резервирования:');if(amount&&!isNaN(amount)&&Number(amount)>0){reserveMaterial(id,Number(amount));renderMaterials()}}));document.querySelectorAll('.pdf-mat').forEach(b=>b.addEventListener('click',function(){exportMaterialPDF(parseInt(this.dataset.id))}))}

function renderProcurements(){const statusFilter=document.getElementById('procurementFilterStatus').value;let procs=getProcurements();if(statusFilter!=='all')procs=procs.filter(p=>p.status===statusFilter);if(!procs.length){procurementBody.innerHTML='<tr><td colspan="7" style="text-align:center;color:var(--text-secondary);">Нет закупок</td></tr>';return}procurementBody.innerHTML=procs.map(p=>'<tr><td>'+p.name+'</td><td>'+(p.type==='grant'?'Грант':p.type==='competition'?'Конкурс':'Прямой договор')+'</td><td>'+p.supplier+'</td><td>'+(p.amount?p.amount.toLocaleString()+' руб.':'—')+'</td><td>'+getStatusBadge(p.status)+'</td><td>'+p.date+'</td><td><button class="btn btn-warning btn-sm edit-proc" data-id="'+p.id+'">✏️</button><button class="btn btn-danger btn-sm delete-proc" data-id="'+p.id+'">🗑️</button><button class="btn btn-success btn-sm pdf-proc" data-id="'+p.id+'">PDF</button></td></tr>').join('');document.querySelectorAll('.edit-proc').forEach(b=>b.addEventListener('click',function(){openEditProcurement(parseInt(this.dataset.id))}));document.querySelectorAll('.delete-proc').forEach(b=>b.addEventListener('click',function(){if(confirm('Удалить закупку?')){deleteProcurement(parseInt(this.dataset.id));renderProcurements()}}));document.querySelectorAll('.pdf-proc').forEach(b=>b.addEventListener('click',function(){exportProcurementPDF(parseInt(this.dataset.id))}))}

function renderSchedule(){const container=scheduleContainer;container.innerHTML='';if(!currentUser){container.innerHTML='<p>Войдите для просмотра</p>';return}if(isAdmin(currentUser)){const users=g(S.users);const schedule=getSchedule();const days=['mon','tue','wed','thu','fri','sat','sun'];const dayLabels=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];const shifts=['day','night','off','remote','sick','vacation'];const shiftLabels={day:'День',night:'Ночь',off:'Выходной',remote:'Удалёнка',sick:'Больничный',vacation:'Отпуск'};users.forEach(u=>{const div=document.createElement('div');div.className='schedule-user';div.innerHTML='<h4>'+(u.displayName||u.login)+'</h4><div class="schedule-grid">';div.innerHTML+='<div class="cell header">День</div>';dayLabels.forEach(d=>div.innerHTML+='<div class="cell header">'+d+'</div>');const s=schedule[u.login]||{};days.forEach(day=>{const val=s[day]||'off';div.innerHTML+='<div class="cell"><select class="schedule-select" data-user="'+u.login+'" data-day="'+day+'">'+shifts.map(sh=>'<option value="'+sh+'" '+(sh===val?'selected':'')+'>'+shiftLabels[sh]+'</option>').join('')+'</select></div>'});div.innerHTML+='</div>';container.appendChild(div)});document.getElementById('saveScheduleBtn').style.display='inline-block'}else{const schedule=getSchedule();const s=schedule[currentUser.login]||{};const days=['mon','tue','wed','thu','fri','sat','sun'];const dayLabels=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];const shiftLabels={day:'День',night:'Ночь',off:'Выходной',remote:'Удалёнка',sick:'Больничный',vacation:'Отпуск'};const div=document.createElement('div');div.className='schedule-user';div.innerHTML='<h4>Моё расписание</h4><div class="schedule-grid">';div.innerHTML+='<div class="cell header">День</div>';dayLabels.forEach(d=>div.innerHTML+='<div class="cell header">'+d+'</div>');days.forEach(day=>{const val=s[day]||'off';div.innerHTML+='<div class="cell">'+shiftLabels[val]+'</div>'});div.innerHTML+='</div>';container.appendChild(div);document.getElementById('saveScheduleBtn').style.display='none'}}

function renderAudit(){if(!isAdmin(currentUser)){auditBody.innerHTML='<tr><td colspan="4" style="text-align:center;color:var(--text-secondary);">Доступно только администратору</td></tr>';return}let logs=g(S.audit);const search=document.getElementById('auditSearch').value.toLowerCase();const userFilter=document.getElementById('auditFilterUser').value;const actionFilter=document.getElementById('auditFilterAction').value;if(search)logs=logs.filter(l=>l.user.toLowerCase().includes(search)||l.action.toLowerCase().includes(search)||(l.details||'').toLowerCase().includes(search));if(userFilter!=='all')logs=logs.filter(l=>l.user===userFilter);if(actionFilter!=='all')logs=logs.filter(l=>l.action===actionFilter);if(!logs.length){auditBody.innerHTML='<tr><td colspan="4" style="text-align:center;color:var(--text-secondary);">Нет записей</td></tr>';return}auditBody.innerHTML=logs.slice(-100).reverse().map(l=>'<tr><td>'+l.time+'</td><td>'+l.user+'</td><td>'+l.action+'</td><td>'+(l.details||'')+'</td></tr>').join('')}

// ------ ЧАТ ------
let currentChatRoom='general';
let chatMediaRecorder=null;let chatAudioChunks=[];
async function renderChat(room){const msgs=await getMsgs(room);chatMessagesContainer.innerHTML=msgs.map(msg=>{const isOwn=currentUser&&msg.sender===currentUser.login;let media='';if(msg.media){if(msg.mediaType==='image')media='<img src="'+msg.media+'" class="media-content" style="max-width:200px;border-radius:10px;">';else if(msg.mediaType==='video')media='<video src="'+msg.media+'" class="media-content" controls style="max-width:200px;border-radius:10px;"></video>';else if(msg.mediaType==='audio'||msg.mediaType==='voice')media='<audio src="'+msg.media+'" class="media-content" controls style="width:100%;"></audio>'}return '<div class="chat-message '+(isOwn?'own':'')+'">'+(msg.text?'<div>'+msg.text+'</div>':'')+media+'<div class="meta"><span>'+msg.sender+'</span><span>'+(msg.time||'')+'</span></div></div>'}).join('');chatMessagesContainer.scrollTop=chatMessagesContainer.scrollHeight}
async function sendChatMessage(text,media=null,mediaType=null){if(!currentUser){showToast('Войдите в систему','error');return}const roomKey=currentChatRoom==='personal'?'personal_'+currentUser.login:currentChatRoom;const msg={sender:currentUser.login,text:text||'',time:new Date().toLocaleTimeString(),timestamp:Date.now(),media,mediaType};await saveMsg(roomKey,msg);renderChat(roomKey);if('Notification' in window&&Notification.permission==='granted'){new Notification('Новое сообщение',{body:msg.sender+': '+(msg.text||'Медиа-файл')})}}
function switchChatRoom(room){currentChatRoom=room;chatRooms.forEach(el=>el.classList.remove('active'));document.querySelector('.chat-room-item[data-room="'+room+'"]').classList.add('active');const roomKey=room==='personal'?'personal_'+currentUser.login:room;renderChat(roomKey)}
function handleMediaCapture(type){if(!currentUser){showToast('Войдите в систему','error');return}const input=document.createElement('input');input.type='file';input.accept=type==='image'?'image/*':type==='video'?'video/*':'audio/*';if(type==='image'||type==='video')input.capture=type==='image'?'environment':'environment';input.onchange=async(e)=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=async(ev)=>{const base64=ev.target.result;await sendChatMessage('',base64,type);input.remove()};reader.readAsDataURL(file)};input.click()}
function toggleVoiceRecord(){if(!currentUser){showToast('Войдите в систему','error');return}if(chatMediaRecorder&&chatMediaRecorder.state==='recording'){chatMediaRecorder.stop();document.getElementById('voiceRecordBtn').classList.remove('active');return}navigator.mediaDevices.getUserMedia({audio:true}).then(stream=>{chatMediaRecorder=new MediaRecorder(stream);chatAudioChunks=[];chatMediaRecorder.ondataavailable=e=>chatAudioChunks.push(e.data);chatMediaRecorder.onstop=async()=>{const blob=new Blob(chatAudioChunks,{type:'audio/webm'});const reader=new FileReader();reader.onload=async(ev)=>{const base64=ev.target.result;await sendChatMessage('',base64,'voice');stream.getTracks().forEach(t=>t.stop())};reader.readAsDataURL(blob);document.getElementById('voiceRecordBtn').classList.remove('active')};chatMediaRecorder.start();document.getElementById('voiceRecordBtn').classList.add('active')}).catch(err=>showToast('Ошибка доступа к микрофону','error'))}

// ------ ПОИСК ------
function globalSearch(query){if(!query.trim())return [];const q=query.toLowerCase();const results=[];getRequests().forEach(r=>{if(r.title.toLowerCase().includes(q)||r.desc.toLowerCase().includes(q)||r.creator.toLowerCase().includes(q))results.push({type:'Заявка',id:r.id,title:r.title,section:'requests'})});getRoutes().forEach(r=>{if(r.vehicle.toLowerCase().includes(q)||r.from.toLowerCase().includes(q)||r.to.toLowerCase().includes(q))results.push({type:'Маршрут',id:r.id,title:r.vehicle+' → '+r.to,section:'transport'})});getMaterials().forEach(m=>{if(m.name.toLowerCase().includes(q)||m.category.toLowerCase().includes(q))results.push({type:'Материал',id:m.id,title:m.name,section:'materials'})});getProcurements().forEach(p=>{if(p.name.toLowerCase().includes(q)||p.supplier.toLowerCase().includes(q))results.push({type:'Закупка',id:p.id,title:p.name,section:'procurement'})});g(S.users).forEach(u=>{if(u.login.toLowerCase().includes(q)||(u.displayName||'').toLowerCase().includes(q))results.push({type:'Пользователь',id:u.login,title:u.displayName||u.login,section:'dashboard'})});return results.slice(0,20)}

// ------ PDF (ГОСТ) ------
async function exportRequestPDF(id){const req=getRequests().find(r=>r.id===id);if(!req)return;const {jsPDF}=window.jspdf;const doc=new jsPDF();doc.setFontSize(16);doc.text('НАКЛАДНАЯ № '+req.id,20,20);doc.setFontSize(12);doc.text('Название: '+req.title,20,40);doc.text('Описание: '+req.desc,20,50);doc.text('Тип: '+req.type,20,60);doc.text('Статус: '+req.status,20,70);doc.text('Приоритет: '+req.priority,20,80);doc.text('Ответственный: '+(req.responsible||'—'),20,90);doc.text('Срок: '+(req.deadline||'—'),20,100);doc.text('Создал: '+req.creator,20,110);doc.text('Дата: '+new Date(req.created).toLocaleString(),20,120);doc.save('nakladnaya_'+req.id+'.pdf')}
async function exportRoutePDF(id){const route=getRoutes().find(r=>r.id===id);if(!route)return;const {jsPDF}=window.jspdf;const doc=new jsPDF();doc.setFontSize(16);doc.text('МАРШРУТНЫЙ ЛИСТ № '+route.id,20,20);doc.setFontSize(12);doc.text('Автомобиль: '+route.vehicle,20,40);doc.text('Тип: '+route.type,20,50);doc.text('Отправление: '+route.from,20,60);doc.text('Доставка: '+route.to,20,70);doc.text('Статус: '+route.status,20,80);doc.text('Дата: '+route.date,20,90);doc.save('marshrut_'+route.id+'.pdf')}
async function exportMaterialPDF(id){const mat=getMaterials().find(m=>m.id===id);if(!mat)return;const {jsPDF}=window.jspdf;const doc=new jsPDF();doc.setFontSize(16);doc.text('НАКЛАДНАЯ НА ВЫДАЧУ МАТЕРИАЛОВ',20,20);doc.setFontSize(12);doc.text('Материал: '+mat.name,20,40);doc.text('Категория: '+mat.category,20,50);doc.text('Ед. изм.: '+mat.unit,20,60);doc.text('Количество: '+mat.quantity,20,70);doc.text('Резерв: '+mat.reserve,20,80);doc.text('Доступно: '+(mat.quantity-mat.reserve),20,90);doc.save('nakladnaya_material_'+mat.id+'.pdf')}
async function exportProcurementPDF(id){const proc=getProcurements().find(p=>p.id===id);if(!proc)return;const {jsPDF}=window.jspdf;const doc=new jsPDF();doc.setFontSize(16);doc.text('ПРОТОКОЛ ЗАКУПКИ № '+proc.id,20,20);doc.setFontSize(12);doc.text('Название: '+proc.name,20,40);doc.text('Тип: '+(proc.type==='grant'?'Грант':proc.type==='competition'?'Конкурс':'Прямой договор'),20,50);doc.text('Поставщик: '+proc.supplier,20,60);doc.text('Сумма: '+(proc.amount?proc.amount.toLocaleString()+' руб.':'—'),20,70);doc.text('Статус: '+proc.status,20,80);doc.text('Дата: '+proc.date,20,90);if(proc.number)doc.text('Номер: '+proc.number,20,100);doc.save('protokol_zakupki_'+proc.id+'.pdf')}

// ------ НАСТРОЙКИ ------
function applySettings(){const settings=g(S.settings);if(settings.theme==='dark'){document.body.classList.add('mto-dark');document.getElementById('themeToggle').textContent='☀️'}else{document.body.classList.remove('mto-dark');document.getElementById('themeToggle').textContent='🌙'}if(settings.compact)document.body.classList.add('compact-mode');else document.body.classList.remove('compact-mode');if(!settings.animations)document.body.classList.add('no-anim');else document.body.classList.remove('no-anim');document.documentElement.style.setProperty('--font-size',(settings.fontSize||14)+'px')}

// ------ ОБНОВЛЕНИЕ ВСЕГО ------
function updateAll(){renderDashboard();renderTransport();renderRequests();renderMaterials();renderProcurements();renderSchedule();renderAudit();if(currentUser){userNameDisplay.textContent=currentUser.displayName||currentUser.login;logoutBtn.style.display='inline-block';document.querySelectorAll('.mto-nav a[data-section]').forEach(link=>{const sec=link.dataset.section;if(sec==='schedule'||sec==='audit'){link.style.display=isAdmin(currentUser)?'inline-block':'none'}else if(sec==='procurement'){const hasAccess=isAdmin(currentUser)||(currentUser.deptPath&&currentUser.deptPath.includes('Начальник склада'));link.style.display=hasAccess?'inline-block':'none'}else{link.style.display='inline-block'}});const roomKey=currentChatRoom==='personal'?'personal_'+currentUser.login:currentChatRoom;renderChat(roomKey);renderUserList();updateBurgerProfile()}else{userNameDisplay.textContent='Гость';logoutBtn.style.display='none'}populateDeptSelects();applySettings()}

function updateBurgerProfile(){const avatar=document.getElementById('burgerAvatar');const name=document.getElementById('burgerName');const role=document.getElementById('burgerRole');if(currentUser){if(currentUser.avatar){avatar.innerHTML='<img src="'+currentUser.avatar+'" alt="avatar">'}else{avatar.innerHTML='👤'}name.textContent=currentUser.displayName||currentUser.login;role.textContent=currentUser.position||getUserRole(currentUser)}else{avatar.innerHTML='👤';name.textContent='Гость';role.textContent='Не авторизован'}}

function renderUserList(){const users=g(S.users);const container=document.getElementById('userList');if(!container)return;container.innerHTML=users.filter(u=>u.login!==currentUser?.login).map(u=>'<div class="chat-room-item" data-room="personal_'+u.login+'" style="font-size:13px;padding:6px 12px;">'+(u.avatar?'<img src="'+u.avatar+'" style="width:24px;height:24px;border-radius:50%;object-fit:cover;">':'👤')+' '+(u.displayName||u.login)+'</div>').join('');container.querySelectorAll('.chat-room-item').forEach(el=>{el.addEventListener('click',function(){const room=this.dataset.room;switchChatRoom(room)})})}

function initAppAfterLogin(){if(!currentUser)return;populateDeptSelects();updateAll();document.getElementById('authOverlay').classList.add('hidden');document.querySelectorAll('.mto-nav a').forEach(a=>a.style.display='inline-block');const roomKey=currentChatRoom==='personal'?'personal_'+currentUser.login:currentChatRoom;renderChat(roomKey);renderUserList();updateBurgerProfile();populateAuditFilters()}

function populateAuditFilters(){const users=g(S.users);const userSelect=document.getElementById('auditFilterUser');userSelect.innerHTML='<option value="all">Все пользователи</option>';users.forEach(u=>{const opt=document.createElement('option');opt.value=u.login;opt.textContent=u.displayName||u.login;userSelect.appendChild(opt)});const actionSelect=document.getElementById('auditFilterAction');const actions=['Вход в систему','Выход','Регистрация','Создание заявки','Изменение заявки','Удаление заявки','Создание маршрута','Изменение маршрута','Удаление маршрута','Создание закупки','Изменение закупки','Удаление закупки','Добавление материала','Изменение материала','Удаление материала','Поставка материала','Резервирование материала','Выдача материала','Добавление ремонта','Завершение ремонта'];actionSelect.innerHTML='<option value="all">Все действия</option>';actions.forEach(a=>{const opt=document.createElement('option');opt.value=a;opt.textContent=a;actionSelect.appendChild(opt)})}

