document.querySelectorAll('.mto-nav a[data-section]').forEach(link=>{link.addEventListener('click',function(e){e.preventDefault();const sec=this.dataset.section;document.querySelectorAll('.mto-section').forEach(s=>s.classList.remove('active'));const target=document.getElementById('section-'+sec);if(target)target.classList.add('active');document.querySelectorAll('.mto-nav a').forEach(a=>a.classList.remove('active'));this.classList.add('active');if(sec==='requests')renderRequests();if(sec==='transport')renderTransport();if(sec==='materials')renderMaterials();if(sec==='procurement')renderProcurements();if(sec==='schedule')renderSchedule();if(sec==='audit')renderAudit();if(sec==='dashboard'){renderDashboard();fetchNews(5,'newsFeedList')}if(sec==='messenger'){const roomKey=currentChatRoom==='personal'?'personal_'+currentUser?.login:currentChatRoom;renderChat(roomKey);renderUserList()}})});

