// ------ МОДАЛКА АУТЕНТИФИКАЦИИ ------
const authOverlay=document.getElementById('authOverlay');const authLogin=document.getElementById('authLogin');const authPassword=document.getElementById('authPassword');const authSubmit=document.getElementById('authSubmit');const authToggle=document.getElementById('authToggle');const authTitle=document.getElementById('authTitle');const authExtra=document.getElementById('authExtra');const authDeptPath=document.getElementById('authDeptPath');const authDisplayName=document.getElementById('authDisplayName');const authPhone=document.getElementById('authPhone');const authEmail=document.getElementById('authEmail');const authPosition=document.getElementById('authPosition');const authBirthDate=document.getElementById('authBirthDate');const authAvatarFile=document.getElementById('authAvatarFile');const authError=document.getElementById('authError');let isLoginMode=true;
function setAuthMode(mode){isLoginMode=(mode==='login');authTitle.textContent=isLoginMode?'Вход в систему':'Регистрация';authSubmit.textContent=isLoginMode?'Войти':'Зарегистрироваться';authToggle.textContent=isLoginMode?'Нет аккаунта? Зарегистрироваться':'Уже есть аккаунт? Войти';authExtra.style.display=isLoginMode?'none':'block';authError.textContent='';populateDeptSelects()}
function handleAuth(){const login=authLogin.value.trim();const password=authPassword.value.trim();if(!login||!password){authError.textContent='Заполните все поля';return}if(isLoginMode){if(loginUser(login,password)){authOverlay.classList.add('hidden');initAppAfterLogin()}else authError.textContent='Неверный логин или пароль'}else{const deptPath=authDeptPath.value;const displayName=authDisplayName.value.trim()||login;const phone=authPhone.value.trim();const email=authEmail.value.trim();const position=authPosition.value.trim();const birthDate=authBirthDate.value;let avatarBase64='';if(authAvatarFile.files.length>0){const reader=new FileReader();reader.onload=(e)=>{avatarBase64=e.target.result;if(registerUser(login,password,deptPath,displayName,phone,email,position,birthDate,avatarBase64)){loginUser(login,password);authOverlay.classList.add('hidden');initAppAfterLogin()}else authError.textContent='Пользователь уже существует'};reader.readAsDataURL(authAvatarFile.files[0]);return}if(registerUser(login,password,deptPath,displayName,phone,email,position,birthDate,avatarBase64)){loginUser(login,password);authOverlay.classList.add('hidden');initAppAfterLogin()}else authError.textContent='Пользователь уже существует'}}
authToggle.addEventListener('click',()=>setAuthMode(isLoginMode?'register':'login'));authSubmit.addEventListener('click',handleAuth);authLogin.addEventListener('keydown',e=>{if(e.key==='Enter')handleAuth()});authPassword.addEventListener('keydown',e=>{if(e.key==='Enter')handleAuth()});
document.getElementById('gosuslugiBtn').addEventListener('click',()=>oauthLogin('Госуслуги'));document.getElementById('mosruBtn').addEventListener('click',()=>oauthLogin('mos.ru'));

