const requestModal=document.getElementById('requestModal');const reqEditId=document.getElementById('reqEditId');const reqTitle=document.getElementById('reqTitle');const reqDesc=document.getElementById('reqDesc');const reqType=document.getElementById('reqType');const reqAddress=document.getElementById('reqAddress');const reqDept=document.getElementById('reqDept');const reqPriority=document.getElementById('reqPriority');const reqStatus=document.getElementById('reqStatus');const reqDeadline=document.getElementById('reqDeadline');const reqResponsible=document.getElementById('reqResponsible')||{value:''};const reqModalTitle=document.getElementById('reqModalTitle');
function openEditRequest(id){const reqs=getRequests();const req=reqs.find(r=>r.id===id);if(!req)return;reqEditId.value=id;reqTitle.value=req.title;reqDesc.value=req.desc;reqType.value=req.type;reqAddress.value=req.address||'';reqDept.value=req.deptPath;reqPriority.value=req.priority;reqStatus.value=req.status;reqDeadline.value=req.deadline||'';if(reqResponsible)reqResponsible.value=req.responsible||'';reqModalTitle.textContent='Редактирование заявки #'+id;requestModal.classList.remove('hidden');populateDeptSelects()}
document.getElementById('createReqBtn').addEventListener('click',function(){reqEditId.value='';reqTitle.value='';reqDesc.value='';reqType.value='repair';reqAddress.value='';reqDept.value=currentUser?currentUser.deptPath:'Диспетчерская';reqPriority.value='medium';reqStatus.value='new';reqDeadline.value='';if(reqResponsible)reqResponsible.value='';reqModalTitle.textContent='Создание заявки';requestModal.classList.remove('hidden');populateDeptSelects()});
document.getElementById('reqCancelBtn').addEventListener('click',()=>requestModal.classList.add('hidden'));
document.getElementById('reqSaveBtn').addEventListener('click',function(){const title=reqTitle.value.trim();const desc=reqDesc.value.trim();const type=reqType.value;const address=reqAddress.value.trim();const deptPath=reqDept.value;const priority=reqPriority.value;const status=reqStatus.value;const deadline=reqDeadline.value;const responsible=reqResponsible?reqResponsible.value:currentUser.login;if(!title){alert('Введите название');return}const id=reqEditId.value;if(id){updateRequest(parseInt(id),{title,desc,type,address,deptPath,priority,status,deadline,responsible})}else{if(!currentUser){alert('Не авторизован');return}createRequest(title,desc,type,address,deptPath,priority,status,deadline,currentUser.login,responsible)}requestModal.classList.add('hidden');renderRequests();updateAll()});

