const routeModal=document.getElementById('routeModal');const routeEditId=document.getElementById('routeEditId');const routeVehicle=document.getElementById('routeVehicle');const routeType=document.getElementById('routeType');const routeFrom=document.getElementById('routeFrom');const routeTo=document.getElementById('routeTo');const routeStatus=document.getElementById('routeStatus');const routeDate=document.getElementById('routeDate');const routeModalTitle=document.getElementById('routeModalTitle');
function openEditRoute(id){const routes=getRoutes();const route=routes.find(r=>r.id===id);if(!route)return;routeEditId.value=id;routeVehicle.value=route.vehicle;routeType.value=route.type;routeFrom.value=route.from;routeTo.value=route.to;routeStatus.value=route.status;routeDate.value=route.date;routeModalTitle.textContent='Редактирование маршрута #'+id;routeModal.classList.remove('hidden')}
document.getElementById('addRouteBtn').addEventListener('click',function(){routeEditId.value='';routeVehicle.value='ГАЗель NEXT';routeType.value='supply';routeFrom.value='';routeTo.value='';routeStatus.value='planned';routeDate.value=new Date().toISOString().split('T')[0];routeModalTitle.textContent='Добавление маршрута';routeModal.classList.remove('hidden')});
