document.getElementById('routeSaveBtn').addEventListener('click',function(){const vehicle=routeVehicle.value;const type=routeType.value;const from=routeFrom.value.trim();const to=routeTo.value.trim();const status=routeStatus.value;const date=routeDate.value;if(!from||!to){alert('Заполните адреса');return}const id=routeEditId.value;if(id){updateRoute(parseInt(id),{vehicle,type,from,to,status,date})}else{if(!currentUser){alert('Не авторизован');return}createRoute(vehicle,type,from,to,status,date)}routeModal.classList.add('hidden');renderTransport();updateAll()});

