const materialModal=document.getElementById('materialModal');const matEditId=document.getElementById('matEditId');const matName=document.getElementById('matName');const matCategory=document.getElementById('matCategory');const matUnit=document.getElementById('matUnit');const matQuantity=document.getElementById('matQuantity');const matReserve=document.getElementById('matReserve');const matModalTitle=document.getElementById('matModalTitle');
function openEditMaterial(id){const mats=getMaterials();const mat=mats.find(m=>m.id===id);if(!mat)return;matEditId.value=id;matName.value=mat.name;matCategory.value=mat.category;matUnit.value=mat.unit;matQuantity.value=mat.quantity;matReserve.value=mat.reserve;matModalTitle.textContent='Редактирование материала';materialModal.classList.remove('hidden')}
document.getElementById('addMaterialBtn').addEventListener('click',function(){matEditId.value='';matName.value='';matCategory.value='Сантехника';matUnit.value='шт';matQuantity.value=0;matReserve.value=0;matModalTitle.textContent='Добавление материала';materialModal.classList.remove('hidden')});
