document.getElementById('matSaveBtn').addEventListener('click',function(){const name=matName.value.trim();const category=matCategory.value;const unit=matUnit.value.trim();const quantity=parseInt(matQuantity.value)||0;const reserve=parseInt(matReserve.value)||0;if(!name||!unit){alert('Заполните название и единицу');return}const id=matEditId.value;if(id){updateMaterial(parseInt(id),{name,category,unit,quantity,reserve})}else{if(!currentUser){alert('Не авторизован');return}addMaterial(name,category,unit,quantity,reserve)}materialModal.classList.add('hidden');renderMaterials();updateAll()});

