const suppliesModal=document.getElementById('suppliesModal');const suppliesList=document.getElementById('suppliesList');const supplyMaterialName=document.getElementById('supplyMaterialName');const supplyQuantity=document.getElementById('supplyQuantity');
document.getElementById('viewSuppliesBtn').addEventListener('click',function(){const supplies=getSupplies();if(!supplies.length)suppliesList.innerHTML='<p style="color:var(--text-secondary);">Нет поставок</p>';else suppliesList.innerHTML=supplies.slice(-20).reverse().map(s=>'<div style="padding:8px 0;border-bottom:1px solid rgba(0,0,0,0.04);"><strong>'+s.material+'</strong> +'+s.quantity+' <span style="color:var(--text-secondary);">'+s.date+'</span></div>').join('');suppliesModal.classList.remove('hidden')});
document.getElementById('addSupplyBtn').addEventListener('click',function(){const name=supplyMaterialName.value.trim();const qty=parseInt(supplyQuantity.value);if(!name||!qty||qty<=0){alert('Введите название и количество');return}addSupply(name,qty);supplyMaterialName.value='';supplyQuantity.value='';const supplies=getSupplies();suppliesList.innerHTML=supplies.slice(-20).reverse().map(s=>'<div style="padding:8px 0;border-bottom:1px solid rgba(0,0,0,0.04);"><strong>'+s.material+'</strong> +'+s.quantity+' <span style="color:var(--text-secondary);">'+s.date+'</span></div>').join('');renderMaterials()});
