const procurementModal=document.getElementById('procurementModal');const procEditId=document.getElementById('procEditId');const procName=document.getElementById('procName');const procType=document.getElementById('procType');const procSupplier=document.getElementById('procSupplier');const procAmount=document.getElementById('procAmount');const procStatus=document.getElementById('procStatus');const procDate=document.getElementById('procDate');const procNumber=document.getElementById('procNumber');const procModalTitle=document.getElementById('procModalTitle');
function openEditProcurement(id){const procs=getProcurements();const proc=procs.find(p=>p.id===id);if(!proc)return;procEditId.value=id;procName.value=proc.name;procType.value=proc.type;procSupplier.value=proc.supplier;procAmount.value=proc.amount;procStatus.value=proc.status;procDate.value=proc.date;procNumber.value=proc.number||'';procModalTitle.textContent='Редактирование закупки #'+id;procurementModal.classList.remove('hidden')}
document.getElementById('addProcurementBtn').addEventListener('click',function(){procEditId.value='';procName.value='';procType.value='grant';procSupplier.value='';procAmount.value='';procStatus.value='planned';procDate.value=new Date().toISOString().split('T')[0];procNumber.value='';procModalTitle.textContent='Добавление закупки';procurementModal.classList.remove('hidden')});
document.getElementById('procCancelBtn').addEventListener('click',()=>procurementModal.classList.add('hidden'));
document.getElementById('procSaveBtn').addEventListener('click',function(){const name=procName.value.trim();const type=procType.value;const supplier=procSupplier.value.trim();const amount=parseFloat(procAmount.value);const status=procStatus.value;const date=procDate.value;const number=procNumber.value.trim();if(!name||!supplier){alert('Заполните название и поставщика');return}const id=procEditId.value;if(id){updateProcurement(parseInt(id),{name,type,supplier,amount,status,date,number})}else{if(!currentUser){alert('Не авторизован');return}createProcurement(name,type,supplier,amount,status,date,number)}procurementModal.classList.add('hidden');renderProcurements();updateAll()});

