const profileModal=document.getElementById('profileModal');const profileLogin=document.getElementById('profileLogin');const profileDisplayName=document.getElementById('profileDisplayName');const profilePhone=document.getElementById('profilePhone');const profileEmail=document.getElementById('profileEmail');const profilePosition=document.getElementById('profilePosition');const profileBirthDate=document.getElementById('profileBirthDate');const profileAvatarFile=document.getElementById('profileAvatarFile');const profileAvatarPreview=document.getElementById('profileAvatarPreview');const profileDeptPath=document.getElementById('profileDeptPath');const profileNewPassword=document.getElementById('profileNewPassword');
function openProfile(){if(!currentUser)return;profileLogin.value=currentUser.login;profileDisplayName.value=currentUser.displayName||'';profilePhone.value=currentUser.phone||'';profileEmail.value=currentUser.email||'';profilePosition.value=currentUser.position||'';profileBirthDate.value=currentUser.birthDate||'';profileDeptPath.value=currentUser.deptPath||'Диспетчерская';profileNewPassword.value='';if(currentUser.avatar){profileAvatarPreview.src=currentUser.avatar;profileAvatarPreview.style.display='block'}else profileAvatarPreview.style.display='none';profileModal.classList.remove('hidden');populateDeptSelects()}
document.querySelector('.menu-item[data-burger="profile"]').addEventListener('click',function(){closeBurger();openProfile()});
document.getElementById('profileCancelBtn').addEventListener('click',()=>profileModal.classList.add('hidden'));
document.getElementById('profileSaveBtn').addEventListener('click',function(){const displayName=profileDisplayName.value.trim()||currentUser.login;const phone=profilePhone.value.trim();const email=profileEmail.value.trim();const position=profilePosition.value.trim();const birthDate=profileBirthDate.value;const deptPath=profileDeptPath.value;const newPassword=profileNewPassword.value.trim();let avatarBase64=currentUser.avatar||'';if(profileAvatarFile.files.length>0){const reader=new FileReader();reader.onload=(e)=>{avatarBase64=e.target.result;saveProfileData(displayName,phone,email,position,birthDate,deptPath,newPassword,avatarBase64)};reader.readAsDataURL(profileAvatarFile.files[0])}else saveProfileData(displayName,phone,email,position,birthDate,deptPath,newPassword,avatarBase64)});
function saveProfileData(displayName,phone,email,position,birthDate,deptPath,newPassword,avatar){const users=g(S.users);const idx=users.findIndex(u=>u.login===currentUser.login);if(idx!==-1){users[idx].displayName=displayName;users[idx].phone=phone;users[idx].email=email;users[idx].position=position;users[idx].birthDate=birthDate;users[idx].avatar=avatar;users[idx].deptPath=deptPath;if(newPassword)users[idx].password=newPassword;s(S.users,users);currentUser=users[idx];saveSession(currentUser);userNameDisplay.textContent=displayName;showToast('Профиль обновлён','success');profileModal.classList.add('hidden');updateAll()}}

