const settingsModal=document.getElementById('settingsModal');const settingsDarkTheme=document.getElementById('settingsDarkTheme');const settingsNotifications=document.getElementById('settingsNotifications');const settingsCompact=document.getElementById('settingsCompact');const settingsAnimations=document.getElementById('settingsAnimations');const settingsLanguage=document.getElementById('settingsLanguage');const settingsFontSize=document.getElementById('settingsFontSize');
document.querySelector('.menu-item[data-burger="settings"]').addEventListener('click',function(){closeBurger();const settings=g(S.settings);settingsDarkTheme.checked=settings.theme==='dark';settingsNotifications.checked=settings.notifications!==false;settingsCompact.checked=settings.compact||false;settingsAnimations.checked=settings.animations!==false;settingsLanguage.value=settings.language||'ru';settingsFontSize.value=settings.fontSize||14;settingsModal.classList.remove('hidden')});
