document.querySelector('.menu-item[data-burger="news"]').addEventListener('click',function(){closeBurger();newsModal.classList.remove('hidden');(async()=>{const container=newsList;container.innerHTML='Загрузка...';try{const proxy='https://api.allorigins.win/raw?url=';const rss='https://news.yandex.ru/news.rss';const resp=await fetch(proxy+encodeURIComponent(rss));if(!resp.ok)throw new Error('Ошибка');const txt=await resp.text();const parser=new DOMParser();const xml=parser.parseFromString(txt,'text/xml');const items=xml.querySelectorAll('item');let html='';items.forEach(item=>{const title=item.querySelector('title')?.textContent||'Без названия';const pub=item.querySelector('pubDate')?.textContent||'';const link=item.querySelector('link')?.textContent||'#';html+='<div style="padding:12px;border-bottom:1px solid rgba(0,0,0,0.06);"><div style="font-weight:500;"><a href="'+link+'" target="_blank" style="color:var(--primary);text-decoration:none;">'+title+'</a></div><div style="font-size:13px;color:var(--text-secondary);">'+pub+'</div></div>'});container.innerHTML=html||'<p style="color:var(--text-secondary);">Новостей нет</p>'}catch(e){container.innerHTML='<p style="color:var(--text-secondary);">Не удалось загрузить новости</p>'}})()});
